// Single runtime source for the website.
// Generated by: node --env-file=.env.local scripts/importTournament.js <championshipId> --tier <S|A|B|C>
//
// Two shapes in practice:
// - Full tournaments: bracket + groups + formats + mapPool + relatedEvents.
// - Qualifiers: just bracket (no groups/formats/mapPool) — the page renders
//   only the general playoff bracket when `groups` is absent.
//
// Shape of each entry:
// {
//   id: string,
//   championshipId: string | null, // FACEIT championship id — the importer's merge key
//   name: string,
//   logo: string | null,
//   tier: "S" | "A" | "B" | "C",   // editorial only — the importer never sets/changes this
//   location: string,              // e.g. "Online" or "Katowice, Poland"
//   startDate: string,             // ISO date
//   endDate: string,               // ISO date
//   url: string | null,            // external source (FACEIT championship page)
//   prizePool: string | null,      // headline total, e.g. "$50,000"
//   description: string | null,
//
//   formats: {
//     groupStage: string[] | null, // lines, e.g. ["Double elimination Bo3", "- Upper bracket quarter-finals Bo1"]
//     playoffs: string[] | null,
//   } | null,
//
//   teams: [
//     {
//       name: string,
//       logo: string | null,
//       slug: string | null,     // links to /teams/:slug when it matches a local team
//       rank: number | null,     // world rank badge
//       seed: number | null,     // event seed badge
//       region: string | null,   // e.g. "Global", "Europe"
//       qualifierName: string | null, // shown instead of a team once the slot is TBD
//       qualifierId: string | null,   // links to /calendar/:id when the qualifier is tracked
//     }
//   ],
//
//   // A bracket match:
//   // {
//   //   team1: { name, logo, tag } | null,
//   //   team2: { name, logo, tag } | null,
//   //   score1: number | null,
//   //   score2: number | null,
//   //   winner: 1 | 2 | null,
//   //   matchId: string | null,   // links to /match/:id
//   // }
//
//   bracket: {                  // overall Playoffs bracket — used by tournaments AND qualifiers
//     rounds: [{ name: string, matches: BracketMatch[] }]
//   } | null,
//
//   groups: [                   // full tournaments only — the importer never builds this yet
//     {
//       name: string,           // "Group A"
//       upper: [{ name: string, matches: BracketMatch[] }],
//       lower: [{ name: string, matches: BracketMatch[] }] | null,
//       final: BracketMatch | null,  // group decider feeding into the Playoffs bracket
//     }
//   ] | null,
//
//   prizeDistribution: [
//     { place: string, amount: string, team: { name, logo } | null, wide: boolean }
//   ] | null,
//
//   mapPool: string[] | null,   // map names, reuses /maps/{slug}.png assets
//
//   relatedEvents: [
//     { name: string, id: string | null, url: string | null } // id links internally to /calendar/:id
//   ] | null,
//
//   matches: [                  // flat chronological schedule — used when there's no clean
//     {                         // bracket/round data (e.g. Swiss-style ladder finals)
//       id: string | null,      // matchId, links to /match/:id
//       team1: { name, logo, slug } | null,
//       team2: { name, logo, slug } | null,
//       score1: number | null,
//       score2: number | null,
//       date: string | null,
//     }
//   ] | null,
// }
//
// Import rule: we never create new team records from an imported tournament.
// Participants are matched against src/data/teams.generated.js by
// faceitTeamId only for a slug/logo link — an unmatched name just renders
// without a link. Because matches flow through the existing sync + rating
// pipeline once a championship_id is added to scripts/matchSyncConfig.js,
// any participant that IS a tracked team has its rating affected
// automatically; nothing tournament-specific is needed for that.
export { default } from "./tournaments.generated.json";
